import statistics
import time
import numpy as np
import lubridate as L
from lubridate.instants import Date

d = L.ymd("2009-09-02")
a = L.ymd("2001-01-01")
b = L.ymd("2002-01-01")
iv = L.interval(a, b)
x = L.ymd_hms("2010-01-31 03:04:05")

def num(value):
    return np.atleast_1d(np.asarray(value, dtype=float)).reshape(-1)

def secs(value):
    return num(value.seconds)

def slots(value):
    return num(value.slots())

def ivals(value):
    return np.r_[secs(L.int_start(value)), num(L.int_length(value))]

def codes(text):
    return np.array([ord(ch) for ch in str(text)], dtype=float)

def one():
    return ivals(L.interval(a, b))

warm = one()
elapsed = []
for _ in range(20):
    started = time.perf_counter(); one(); elapsed.append((time.perf_counter() - started) * 1000)
print("%.17g" % statistics.median(elapsed))
print(" ".join("%.17g" % float(v) for v in num(one())))

